import re
import sys

semio_cs_path = "./semio/net/Semio/Semio.cs"
gh_cs_path = "./semio/gh/Semio.Grasshopper/Semio.Grasshopper.cs"

with open(semio_cs_path, "r") as f:
    semio_cs = f.read()

# Extract models
class_blocks = re.findall(r"public class (\w+Diff) : Entity<\1>\s*\{([^}]*)\}", semio_cs, re.MULTILINE)
diff_models = {}
for class_name, body in class_blocks:
    props = []
    lines = body.split("\n")
    for line in lines:
        line = line.strip()
        if line.startswith("public ") and "{ get =>" in line:
            parts = line.split()
            if len(parts) >= 3:
                prop_type = parts[1]
                prop_name = parts[2]
                if prop_type.endswith("?"):
                    prop_type = prop_type[:-1]
                props.append((prop_type, prop_name))
    diff_models[class_name] = props

with open(gh_cs_path, "r") as f:
    gh_cs = f.read()

# Find existing params so we know what is available
available_params = set(re.findall(r"public class (\w+Param)\s*:", gh_cs))
available_goos = set(re.findall(r"public class (\w+Goo)\s*:", gh_cs))

type_to_gh_param = {
    "string": "Text",
    "bool": "Boolean",
    "DateTime": "Time",
    "double": "Number",
    "int": "Integer",
    "long": "Integer",
    "float": "Number",
}

def get_abbrev(name):
    caps = ''.join(c for c in name if c.isupper())
    if len(caps) > 1: return caps
    if len(name) >= 2: return name[:2]
    return name

def generate_methods(model_name):
    if model_name not in diff_models or len(diff_models[model_name]) == 0:
        return None

    props = diff_models[model_name]

    input_params = []
    output_params = []
    get_data = []
    set_data = []

    for i, (prop_type, prop_name) in enumerate(props):
        is_list = False
        if prop_type.startswith("List<"):
            is_list = True
            prop_type = prop_type[5:-1] # get inner type

        gh_access = "GH_ParamAccess.list" if is_list else "GH_ParamAccess.item"
        abbrev = get_abbrev(prop_name)
        if not is_list: abbrev += "?"
        else: abbrev += "*"

        idx = i + 2
        camel_name = prop_name[:1].lower() + prop_name[1:]

        if prop_type in type_to_gh_param:
            param_type = type_to_gh_param[prop_type]
            param_add = f'pManager.Add{param_type}Parameter("{prop_name}", "{abbrev}", "The optional {prop_name.lower()}.", {gh_access});'

            if param_type == "Text":
                get_data.append(f'string {camel_name}Str = null;')
                get_data.append(f'if (DA.GetData({idx}, ref {camel_name}Str)) model.{prop_name} = {camel_name}Str;')
            elif param_type == "Boolean":
                get_data.append(f'bool {camel_name}Val = default;')
                get_data.append(f'if (DA.GetData({idx}, ref {camel_name}Val)) model.{prop_name} = {camel_name}Val;')
            elif param_type == "Time":
                if prop_type == "string":
                    get_data.append(f'string {camel_name}Str = null;')
                    get_data.append(f'if (DA.GetData({idx}, ref {camel_name}Str)) model.{prop_name} = {camel_name}Str;')
                else:
                    get_data.append(f'DateTime {camel_name}Val = default;')
                    get_data.append(f'if (DA.GetData({idx}, ref {camel_name}Val)) model.{prop_name} = {camel_name}Val;')
            else:
                get_data.append(f'double {camel_name}Val = default;')
                get_data.append(f'if (DA.GetData({idx}, ref {camel_name}Val)) model.{prop_name} = {camel_name}Val;')

            set_data.append(f'if (model.ShouldSerialize{prop_name}()) DA.SetData({idx}, model.{prop_name});')

        else:
            param_name = prop_type + "Param"
            goo_name = prop_type + "Goo"

            # fallback to generic parameter if not found
            if param_name not in available_params:
                # If we don't have a param, we use generic
                param_add = f'pManager.AddGenericParameter("{prop_name}", "{abbrev}", "The optional {prop_name.lower()}.", {gh_access});'
                if is_list:
                    get_data.append(f'var {camel_name} = new List<{prop_type}>();')
                    get_data.append(f'if (DA.GetDataList({idx}, {camel_name})) model.{prop_name} = {camel_name};')
                    set_data.append(f'if (model.ShouldSerialize{prop_name}() && model.{prop_name} is not null) DA.SetDataList({idx}, model.{prop_name});')
                else:
                    get_data.append(f'{prop_type} {camel_name} = null;')
                    get_data.append(f'if (DA.GetData({idx}, ref {camel_name})) model.{prop_name} = {camel_name};')
                    set_data.append(f'if (model.ShouldSerialize{prop_name}() && model.{prop_name} is not null) DA.SetData({idx}, model.{prop_name});')
            else:
                param_add = f'pManager.AddParameter(new {param_name}(), "{prop_name}", "{abbrev}", "The optional {prop_name.lower()}.", {gh_access});'
                if is_list:
                    get_data.append(f'var {camel_name} = new List<{goo_name}>();')
                    get_data.append(f'if (DA.GetDataList({idx}, {camel_name})) model.{prop_name} = {camel_name}.Select(x => x.Value?.DeepClone()).ToList();')
                    set_data.append(f'if (model.ShouldSerialize{prop_name}() && model.{prop_name} is not null) DA.SetDataList({idx}, model.{prop_name}.Select(x => new {goo_name}(x.DeepClone())).ToList());')
                else:
                    get_data.append(f'var {camel_name} = new {goo_name}();')
                    get_data.append(f'if (DA.GetData({idx}, ref {camel_name})) model.{prop_name} = {camel_name}.Value?.DeepClone();')
                    set_data.append(f'if (model.ShouldSerialize{prop_name}() && model.{prop_name} is not null) DA.SetData({idx}, new {goo_name}(model.{prop_name}.DeepClone()));')

        input_params.append(f'        {param_add}')
        output_params.append(f'        {param_add}')

    methods = f"""
    protected override void RegisterModelInputParams(GH_InputParamManager pManager)
    {{
{chr(10).join(input_params)}
    }}

    protected override void RegisterModelOutputParams(GH_OutputParamManager pManager)
    {{
{chr(10).join(output_params)}
    }}

    protected override void GetModelData(IGH_DataAccess DA, {model_name} model)
    {{
{chr(10).join("        " + x for x in get_data)}
    }}

    protected override void SetModelData(IGH_DataAccess DA, {model_name} model)
    {{
{chr(10).join("        " + x for x in set_data)}
    }}"""
    return methods

components_updated = 0
for comp_name in re.findall(r"public class (\w+DiffComponent) : DiffComponent", gh_cs):
    model_name = comp_name.replace("Component", "")
    methods = generate_methods(model_name)
    if methods:
        pattern = r"(public class " + comp_name + r"\s*:\s*DiffComponent<[^>]+>\s*\{.*?IconResourceName => .*?;)"
        start_match = re.search(pattern, gh_cs, re.DOTALL)
        if start_match:
            start_idx = start_match.end()
            brace_count = 0
            end_idx = -1
            found_first_brace = False
            for i in range(start_match.start(), len(gh_cs)):
                char = gh_cs[i]
                if char == '{':
                    brace_count += 1
                    found_first_brace = True
                elif char == '}':
                    brace_count -= 1
                if found_first_brace and brace_count == 0:
                    end_idx = i
                    break
            if end_idx != -1:
                gh_cs = gh_cs[:start_idx] + "\n" + methods + "\n" + gh_cs[end_idx:]
                components_updated += 1

with open(gh_cs_path, "w") as f:
    f.write(gh_cs)

print(f"Force updated {components_updated} Diff components safely.")
EOF
